// Saved IMU measurement only: no device access or vehicle-control API.
(() => {
  const imuOverviewBase = overview;
  overview = async function () {
    await imuOverviewBase();
    if (route !== 'overview' || $('imuMountReport')) return;
    const reportURL = '/experiment/imu_mount_20261019/summary.json';
    try {
      const response = await fetch(reportURL, {cache: 'no-store'});
      if (!response.ok) return;
      const r = await response.json();
      if (route !== 'overview' || $('imuMountReport')) return;
      const gyro = r.vehicle_gyro_dps_holdout.map(s => Number(s.mean).toFixed(3)).join(' / ');
      const norm = Number(r.corrected_accel_norm_g_holdout.mean).toFixed(3);
      const passed = r.status === 'stationary_screen_pass';
      $('main').insertAdjacentHTML('beforeend', `<section class="card" id="imuMountReport">
        <span class="badge">Orin 實測紀錄 · 2026-10-19 · 非即時</span>
        <h2>MPU6050 裝車方向與靜止檢查</h2>
        <p>${passed ? '靜止檢查通過' : '需檢查量測結果'}：${Number(r.samples)} 筆，讀取錯誤 ${Number(r.errors)} 次。校正後加速度大小平均 <b>${norm}g</b>；三軸角速度平均 ${gyro} °/s。</p>
        <p>接腳排朝車頭、晶片朝上；車身座標為 X 向前、Y 向左、Z 向上。先在感測器座標校正，再將 X、Y 反號，Z 不變。設定已用於獨立 IMU 診斷程式，未接入車控。</p>
        <p class="note">前段估計陀螺儀零偏，後段獨立驗證。車頭與左右方向依使用者安裝說明及先前六面辨識設定；靜止量測無法驗證水平軸方向。尚未驗證行駛振動、長時間漂移及不同溫度；不可視為自動行駛驗收。</p>
        <a href="${reportURL}" target="_blank" rel="noopener">查看本次摘要 JSON</a>
      </section>`);
    } catch (error) {
      console.warn('Saved IMU report unavailable', error);
    }
  };
})();


