/* Manual push route audit r2 */
(()=>{
 const root='/experiment/entrance-reference-20261030/';
 let rows=[],idx=0,playing=false,clock=0,time0=0,epoch=0,loadEpoch=0;
 const q=id=>document.getElementById(id);
 function stop(){playing=false;if(q('erPlay'))q('erPlay').textContent='播放完整片段';}
 function draw(){
  if(!rows.length||!q('erCanvas'))return;
  const r=rows[idx];q('erSlider').value=idx;
  q('erTime').textContent=`${idx+1}/${rows.length} · ${r.t.toFixed(3)} 秒 · 原圖時間差 ${r.video_delta_ms.toFixed(0)} ms`;
  const states={STRAIGHT_PAIR:'當張配對成立',PENDING:'候選尚待連續確認',ORDINARY:'沒有符合條件的直行配對'};
  q('erState').textContent=`${states[r.state]||r.state}。${r.candidate_path.length?'綠線為離線候選；遠處有線、近處缺邊界時，虛線是規劃連接。':'本格沒有綠色直行路徑；黃色只顯示原算法，沒有冒充修正結果。'}`;
  q('erDetail').textContent=JSON.stringify({reason:r.reason,candidates:r.candidates.length,observed_rows:r.observed_rows,entrance:r.entrance,source:'只用當前遮罩及之前影格；未使用人工出口座標或未來影格'},null,2);
  let token=++epoch,im=new Image();im.onload=()=>{
   if(token!==epoch||!q('erCanvas'))return;
   const c=q('erCanvas').getContext('2d');c.drawImage(im,0,0,640,360);
   function line(points,color,dash=[]){if(points.length<2)return;c.strokeStyle=color;c.lineWidth=2;c.setLineDash(dash);c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x/2,y/2):c.moveTo(x/2,y/2));c.stroke();c.setLineDash([]);}
   if(q('erBase').checked)line(r.baseline,'#ffc135');
   if(q('erOld').checked)line(r.r1_path,'#a589ff');
   if(q('erNew').checked&&r.candidate_path.length){
    const hi=Math.max(...r.observed_rows)*2,lo=Math.min(...r.observed_rows)*2;
    line(r.candidate_path,'#16eb75',[7,4]);
    if(hi>=432)line(r.candidate_path.filter(p=>p[1]>=lo&&p[1]<=hi),'#16eb75');
   }
   if(q('erEdges').checked&&r.selected){
    for(const side of ['left','right']){const e=r.selected[side],ys=[e.lo,e.hi];line(ys.map(y=>[(e.fit[0]*y+e.fit[1])*2,y*2]),'#38c9ff');}
   }
  };im.src=root+r.image;
 }
 function tick(t){if(!playing||!q('erCanvas')){stop();return;}let next=idx,sec=time0+(t-clock)/1000*Number(q('erSpeed').value);while(next<rows.length-1&&rows[next+1].t<=sec)next++;if(next!==idx){idx=next;draw();}if(idx===rows.length-1)stop();else requestAnimationFrame(tick);}
 async function load(){stop();const token=++loadEpoch;rows=[];epoch++;q('erTime').textContent='載入完整片段…';try{const res=await fetch(root+q('erRun').value+'-player.json');if(!res.ok)throw Error(res.status);const data=await res.json();if(token!==loadEpoch||!q('erCanvas'))return;rows=data;idx=0;q('erSlider').max=rows.length-1;draw();}catch(e){if(q('erTime'))q('erTime').textContent='載入失敗：'+e.message;}}
 function mount(){
  if(location.hash!=='#models'){stop();return;}
  if(!q('main')||q('entranceReferenceReview')||window.WBArchive?.hold('entranceReferenceReview'))return;
  q('main').insertAdjacentHTML('afterbegin',`<section class="card" id="entranceReferenceReview"><h2>手推雙路口核對 r2 · 入口方向與路寬（僅離線）</h2>
  <p>兩段影片由使用者手推，通道走法是正確的一種可能；不是精確中心線或PID行駛真值。候選只從前三張合格入口雙邊界估計像素路寬與方向，之後以當張線段和先前方向比較，不讀未來出口。</p>
  <p><b>完整穿越仍未通過。</b>入口候選較完整，但第一段有短線／斜向外推，第二段109–114秒仍會失去候選。候選輸出：第一段18→131／171格、第二段65→125／181格；不是正確率。固定0.6列無目標：原版0／17、r1為5／29、r2為25／21。不能據此部署PID。未連車、未修改保存參數。</p>
  <label>完整片段 <select id="erRun"><option value="first">手推第一完整路口 65–82秒</option><option value="second">手推第二完整路口 102–120秒</option></select></label>
  <button id="erPlay">播放完整片段</button><button id="erPrev" class="secondary">上一格</button><button id="erNext" class="secondary">下一格</button>
  <label>播放速度 <select id="erSpeed"><option value="1">1倍</option><option value="0.5">0.5倍</option><option value="0.25">0.25倍</option></select></label>
  <input id="erSlider" type="range" min="0" max="0" value="0" step="1" style="width:100%"><p id="erTime"></p>
  <label><input id="erBase" type="checkbox" checked>黃色原版</label><label><input id="erOld" type="checkbox">紫色前版r1</label><label><input id="erNew" type="checkbox" checked>綠色直行候選</label><label><input id="erEdges" type="checkbox">青色配對線段</label>
  <canvas id="erCanvas" width="640" height="360" style="width:100%;max-width:960px;background:#20302e;border-radius:12px"></canvas><p id="erState"></p>
  <details><summary>這格的來源與配對診斷</summary><pre id="erDetail" style="white-space:pre-wrap;max-height:300px;overflow:auto"></pre></details>
  <p><a href="${root}report.json">整段統計及未通過項目</a> · <a href="${root}tests.json">機制檢查（非路口成功率）</a></p></section>`);
  q('erRun').onchange=load;q('erSlider').oninput=()=>{stop();idx=Number(q('erSlider').value);draw();};
  for(const id of ['erBase','erOld','erNew','erEdges'])q(id).onchange=draw;
  q('erPrev').onclick=()=>{stop();idx=Math.max(0,idx-1);draw();};q('erNext').onclick=()=>{stop();idx=Math.min(rows.length-1,idx+1);draw();};
  q('erSpeed').onchange=stop;q('erPlay').onclick=()=>{if(playing){stop();return;}if(!rows.length)return;if(idx===rows.length-1)idx=0;playing=true;clock=performance.now();time0=rows[idx].t;q('erPlay').textContent='暫停';draw();requestAnimationFrame(tick);};load();
 }
 window.addEventListener('hashchange',()=>setTimeout(mount,900));setInterval(mount,2000);mount();
})();

