  q('jcRun').onchange=load;q('jcSeg').onchange=table;q('jcSlider').oninput=()=>{stop();idx=Number(q('jcSlider').value);draw();};
  for(const id of ['jcBase','jcR1','jcR2','jcNew','jcEdges'])q(id).onchange=draw;
  q('jcPrev').onclick=()=>{stop();idx=Math.max(0,idx-1);draw();};q('jcNext').onclick=()=>{stop();idx=Math.min(rows.length-1,idx+1);draw();};
  q('jcSpeed').onchange=stop;q('jcPlay').onclick=()=>{if(playing){stop();return;}if(!rows.length)return;if(idx===rows.length-1)idx=0;playing=true;clock=performance.now();time0=rows[idx].t;q('jcPlay').textContent='暫停';draw();requestAnimationFrame(tick);};
  fetch(root+'compare.json').then(r=>r.json()).then(d=>{stats=d;segs();}).catch(()=>{});
  fetch(root+'agreement.json').then(r=>r.json()).then(d=>{if(!q('jcAgree'))return;q('jcAgree').innerHTML='<table><thead><tr><th>輪次</th><th>車上算法</th><th>兩者都有</th><th>中位差px</th><th>P90差px</th><th>≤20px</th><th>>40px</th><th>只有車上有</th></tr></thead><tbody>'+Object.entries(d.runs).map(([k,v])=>`<tr><td>${k}</td><td>${v.algorithm}</td><td>${v.both}</td><td>${v.abs_diff_median}</td><td>${v.abs_diff_p90}</td><td>${v.agree_le20}</td><td>${v.over40}</td><td>${v.car_only}</td></tr>`).join('')+'</tbody></table>';}).catch(()=>{});load();
