  fetch('/experiment/handpush-newpose-20261031/8530/events.json').then(r=>r.json()).then(d=>{const sel=q('js8530Sel'),img=q('js8530Img');if(!sel)return;sel.innerHTML=d.strips.map((x,i)=>`<option value="${i}">${x.variant==='r1'?'原r1':'候選handback'} ${x.t}秒 ${x.before}→${x.after} ${x.reason}（跳動${x.jump==null?'—':x.jump}px）</option>`).join('');const show8=()=>{img.src='/experiment/handpush-newpose-20261031/8530/events/'+d.strips[Number(sel.value)].image;};sel.onchange=show8;show8();}).catch(()=>{});
